      </GuestShell>
    );
  }
  if (path === "/login") {
    return (
      <GuestShell path={path}>
        <LoginPage />
      </GuestShell>
    );
  }
  if (path === "/") {
    return (
      <AppShell path={path}>
        <DashboardMain />
      </AppShell>
    );
  }
  if (path === "/pages") {
    return (
      <AppShell path={path}>
        <Pages search={search} />
      </AppShell>
    );
  }
  if (path === "/search") {
    return (
      <AppShell path={path}>
        <SearchPage search={search} />
      </AppShell>
    );
  }
  if (path === "/gallery") {
    return (
      <AppShell path={path}>
        <MediaGallery />
      </AppShell>
    );
  }
  if (path === "/sitemap") {
    return (
      <AppShell path={path}>
        <SitemapPage />
      </AppShell>
    );
  }
  if (path === "/redirects") {
    return (
      <AppShell path={path}>
        <RedirectsPage />
      </AppShell>
    );
  }
  if (path === "/convert-divi") {
    return (
      <AppShell path={path}>
        <ConvertDiviPage />
      </AppShell>
    );
  }
  if (path === "/library") {
    return (
      <AppShell path={path}>
        <LibraryPage />
      </AppShell>
    );
  }
  if (path.startsWith("/library/")) {
    const id = path.split("/")[2];
    return (
      <AppShell path={path}>
        <LibraryDetailPage id={id} />
      </AppShell>
    );
  }

  return <div className="">Not found</div>;
}

