import { useCallback, useEffect, useRef, useState } from "react";
import { Field } from "@base-ui/react/field";
import { Form } from "@base-ui/react/form";
import { Slider } from "../../components/ui/slider";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../../components/ui/select";
import { usePublish } from "../../usePublish";
import "./ParameterController.css";

// ─── Types ────────────────────────────────────────────────────────────────────

export type ParameterType = "string" | "number";
export type ParameterWidget = "slider" | "input" | "select";

export interface ParameterConfig {
  /** Display label shown above the control. */
  title: string;
  /** JSON schema type. */
  type: ParameterType;
  /** Default value applied on mount. */
  default: number | string;
  /** Minimum value — for slider and number input. */
  minimum?: number;
  /** Maximum value — for slider and number input. */
  maximum?: number;
  /** Step increment — for slider and number input. */
  multipleOf?: number;
  /** Options list — for select. */
  enum?: string[];
  /** Widget rendering options. */
  "x-options"?: {
    widget?: ParameterWidget;
  };
}

export interface ParameterControllerProps {
  /**
   * EventBus channel to publish parameter updates to.
   * Default: "params/control"
   */
  channel?: string;
  /**
   * Parameter definitions keyed by parameter name.
   * The key is used as the field name in the published payload.
   */
  parameters?: Record<string, ParameterConfig>;
  /**
   * Debounce delay in milliseconds for slider controls.
   * Default: 300
   */
  debounceMs?: number;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function resolveWidget(config: ParameterConfig): ParameterWidget {
  const explicit = config["x-options"]?.widget;
  if (explicit) return explicit;
  if (config.enum) return "select";
  return "input";
}

function initialValues(
  parameters: Record<string, ParameterConfig>,
): Record<string, number | string> {
  return Object.fromEntries(
    Object.entries(parameters).map(([key, config]) => [key, config.default]),
  );
}

// ─── Component ────────────────────────────────────────────────────────────────

const PREFIX = "sct-ParameterController";

export function ParameterControllerComponent({
  channel = "params/control",
  parameters,
  debounceMs = 300,
}: ParameterControllerProps) {
  const publish = usePublish();
  const [values, setValues] = useState<Record<string, number | string>>(() =>
    parameters && Object.keys(parameters).length > 0 ? initialValues(parameters) : {},
  );

  const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (parameters && Object.keys(parameters).length > 0) {
      setValues(initialValues(parameters));
    } else {
      setValues({});
    }
  }, [parameters]);

  useEffect(() => {
    return () => {
      if (debounceTimer.current) clearTimeout(debounceTimer.current);
    };
  }, []);

  const publishValues = useCallback(
    (nextValues: Record<string, number | string>) => {
      publish(channel, nextValues);
    },
    [channel, publish],
  );

  const handleChange = useCallback(
    (key: string, value: number | string, debounce = false) => {
      const nextValues = { ...values, [key]: value };
      setValues(nextValues);

      if (debounce) {
        if (debounceTimer.current) clearTimeout(debounceTimer.current);
        debounceTimer.current = setTimeout(() => {
          publishValues(nextValues);
        }, debounceMs);
      } else {
        publishValues(nextValues);
      }
    },
    [values, debounceMs, publishValues],
  );

  if (!parameters || Object.keys(parameters).length === 0) {
    return <div className={`${PREFIX}-empty`}>No parameters configured</div>;
  }

  return (
    // Form with no submit button — publishes on each field change.
    // validationMode="onChange" ensures Field errors update live.
    <Form
      className={`${PREFIX}-container`}
      validationMode="onChange"
      onFormSubmit={() => {
        // No-op: submission is driven by individual field onChange handlers.
        // The Form wrapper is here for semantic correctness and Field context.
      }}
    >
      {Object.entries(parameters).map(([key, config]) => {
        const widget = resolveWidget(config);
        const value = values[key] ?? config.default;

        return (
          <Field.Root key={key} name={key} className={`${PREFIX}-row`}>
            <Field.Label className={`${PREFIX}-label`} htmlFor={`param-${key}`}>
              {config.title}
            </Field.Label>

            <div className={`${PREFIX}-control`}>
              {widget === "slider" && (
                <div className={`${PREFIX}-slider-wrapper`}>
                  <Slider
                    key={`${key}-${config.default}`}
                    id={`param-${key}`}
                    aria-label={config.title}
                    min={config.minimum ?? 0}
                    max={config.maximum ?? 100}
                    step={config.multipleOf ?? 1}
                    defaultValue={config.default as number}
                    onValueChange={(newValue) => {
                      handleChange(key, newValue as number, true);
                    }}
                  />
                  <span className={`${PREFIX}-value`}>
                    {(value as number).toLocaleString()}
                  </span>
                </div>
              )}

              {widget === "input" && (
                // Field.Root ancestor satisfies useFieldRootContext
                // used internally by base-ui Input.
                <Field.Control
                  id={`param-${key}`}
                  aria-label={config.title}
                  className={`${PREFIX}-input`}
                  type="number"
                  min={config.minimum}
                  max={config.maximum}
                  step={config.multipleOf}
                  value={String(value)}
                  onChange={(e) =>
                    handleChange(key, (e.target as HTMLInputElement).valueAsNumber)
                  }
                />
              )}

              {widget === "select" && (
                <Select
                  value={value as string}
                  onValueChange={(v: string | null) =>
                    v !== null && handleChange(key, v)
                  }
                >
                  <SelectTrigger
                    id={`param-${key}`}
                    aria-label={config.title}
                    className={`${PREFIX}-select-trigger`}
                  >
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {config.enum?.map((option) => (
                      <SelectItem key={option} value={option}>
                        {option}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            </div>
          </Field.Root>
        );
      })}
    </Form>
  );
}

import { Field } from '@base-ui/react/field';
import { useMutation } from '@tanstack/react-query';
import { UndoIcon } from 'lucide-react';
import { useEffect, useState } from 'react';
import { type FieldValues, type Path, useFormContext, useWatch } from 'react-hook-form';
import { useTranslation } from 'react-i18next';
// biome-ignore lint/style/noRestrictedImports: colocated mutation; single-use validator hook scoped to this form field.
import { type CheckSlugData, type CheckSlugResponse, checkSlug } from 'sdk';
import type { ChannelEntityType } from 'shared';
import slugify from 'slugify';
import { useOnlineManager } from '~/hooks/use-online-manager';
import type { ApiError } from '~/lib/api';
import type { BaseFormFieldProps } from '~/modules/common/form-fields/type';
import { Button } from '~/modules/ui/button';
import { FormDescription, FormField, FormItem, FormLabel, FormMessage } from '~/modules/ui/field';
import { InputGroup, InputGroupAddon, InputGroupInput, InputGroupText } from '~/modules/ui/input-group';
import { cn } from '~/utils/cn';

type SlugFieldProps<TFieldValues extends FieldValues> = Omit<BaseFormFieldProps<TFieldValues>, 'name'> & {
  entityType: ChannelEntityType | 'user';
  tenantId?: string;
  nameValue?: string;
  description?: string;
  previousSlug?: string;
  prefix?: string;
};

/** Inner input that uses Field.Control for automatic label/aria association */
function SlugInput(props: React.ComponentProps<typeof InputGroupInput>) {
  return <Field.Control render={<InputGroupInput {...props} />} />;
}

/**
 * Form field for entering a URL slug with auto-generation from a name and availability checking.
 */
export function SlugFormField<TFieldValues extends FieldValues>({
  control,
  label,
  previousSlug,
  description,
  nameValue,
  entityType,
  tenantId,
  prefix: customPrefix,
}: SlugFieldProps<TFieldValues>) {
  const { t } = useTranslation();
  const isOnline = useOnlineManager();

  const name = 'slug';

  const [isDeviating, setDeviating] = useState(false);
  const [isSlugAvailable, setSlugAvailable] = useState<'available' | 'blank' | 'notAvailable'>('blank');

  const prefix = customPrefix;

  const inputClassName = `${isSlugAvailable !== 'blank' && 'ring-2 sm:focus-visible:ring-2'}
                          ${isSlugAvailable === 'available' && 'ring-green-500 focus-visible:ring-green-500'}
                          ${isSlugAvailable === 'notAvailable' && 'ring-red-500 focus-visible:ring-red-500'}`;

  const form = useFormContext<{ slug: string }>();

  // Watch to check if slug availability
  const slug = useWatch({ control: form.control, name: name });

  // Check if slug is available
  const { mutate: checkAvailability } = useMutation<CheckSlugResponse, ApiError, NonNullable<CheckSlugData['body']>>({
    mutationKey: [name],
    mutationFn: async (body) => {
      if (!tenantId) return;
      return await checkSlug({ path: { tenantId }, body });
    },
    onSuccess: () => {
      if (!isValidSlug(slug)) return;
      form.clearErrors(name);
      setSlugAvailable('available');
    },
    onError: () => {
      form.setError(name, { type: 'manual', message: t('error:slug_exists') });
      setSlugAvailable('notAvailable');
    },
  });

  // Only show green ring if slug is valid
  const isValidSlug = (value: string) => {
    if (!value || value.trim().length < 2) return false;
    return /^[a-z0-9]+(-[a-z0-9]+)*$/.test(value);
  };

  // Check on change
  useEffect(() => {
    if (slug.length < 2 || (isValidSlug(slug) && previousSlug && previousSlug === slug))
      return setSlugAvailable('blank');
    if (isValidSlug(slug)) {
      if (!isOnline) return;
      // Skip availability check for user slugs (globally unique, handled by update API)
      if (entityType === 'user' || !tenantId) return;

      return checkAvailability({ slug, entityType });
    }
    if (!isValidSlug(slug)) return setSlugAvailable('notAvailable');
  }, [slug]);

  // In create forms, auto-generate slug from name
  useEffect(() => {
    if (previousSlug || isDeviating) return;
    form.setValue(name, slugify(nameValue || '', { lower: true, strict: true }));
  }, [nameValue]);

  // Revert to previous slug
  const revertSlug = () => {
    form.resetField(name);
  };

  return (
    <FormField
      control={control}
      name={name as Path<TFieldValues>}
      render={({ field: { value: formFieldValue, ...rest } }) => (
        <FormItem name={name}>
          <FormLabel>
            {label}
            <span className="ml-1 opacity-50">*</span>
          </FormLabel>
          {description && <FormDescription>{description}</FormDescription>}
          <InputGroup className={cn('', inputClassName)}>
            <SlugInput type={entityType} onFocus={() => setDeviating(true)} value={formFieldValue || ''} {...rest} />
            {prefix && (
              <InputGroupAddon>
                <InputGroupText id="slug-prefix" className="text-xs" style={{ opacity: formFieldValue ? 1 : 0.5 }}>
                  {prefix}
                </InputGroupText>
              </InputGroupAddon>
            )}

            {previousSlug && previousSlug !== slug && (
              <InputGroupAddon align="inline-end">
                <Button
                  variant="ghost"
                  size="sm"
                  aria-label={t('c:revert_handle')}
                  onClick={revertSlug}
                  className="h-full"
                >
                  <UndoIcon /> <span className="ml-1 max-sm:hidden">{t('c:revert')}</span>
                </Button>
              </InputGroupAddon>
            )}
          </InputGroup>
          <FormMessage />
        </FormItem>
      )}
    />
  );
}
